// Tintero client: HTTPS with a per-device certificate.

#include "tintero.h"

#include <HTTPClient.h>
#include <WiFi.h>
#include <WiFiClientSecure.h>

// Generated by `npm run pki -- firmware`; git ignores it. It defines TINTERO_HOST,
// TINTERO_DEVICE_ID, TINTERO_CA_PEM, TINTERO_DEVICE_CERT_PEM and TINTERO_DEVICE_KEY_PEM.
#include "tintero_certs.h"

namespace tintero {
namespace {

constexpr uint16_t PORT = 443;
constexpr int32_t CONNECT_TIMEOUT_MS = 10000;      // opening the TCP connection
constexpr uint16_t READ_TIMEOUT_MS = 20000;        // waiting for data from the server
constexpr unsigned long HANDSHAKE_TIMEOUT_S = 15;  // TLS handshake

constexpr char FIRMWARE[] = "esp32-0.1";
constexpr char PANEL[] = "w=800,h=480,dpi=124,depth=1";  // GDEY075T7

char view[17] = "";  // for the Tintero-View header

WiFiClientSecure tls;  // the encrypted connection; HTTPClient writes and reads through it
HTTPClient http;

// A write target with a cap: HTTPClient hands it the body of the answer piece by
// piece and it copies it into the buffer until the buffer is full. If one byte
// too many arrives, it returns 0 and HTTPClient stops reading with an error.
class BoundedSink : public Stream {
 public:
  BoundedSink(uint8_t *buf, size_t cap) : buf_(buf), cap_(cap) {}

  size_t write(uint8_t b) override { return write(&b, 1); }
  size_t write(const uint8_t *data, size_t n) override {
    if (n > cap_ - len_) {
      overflow_ = true;
      return 0;
    }
    memcpy(buf_ + len_, data, n);
    len_ += n;
    return n;
  }
  // It is only written to; reading makes no sense.
  int available() override { return 0; }
  int read() override { return -1; }
  int peek() override { return -1; }

  size_t length() const { return len_; }
  bool overflow() const { return overflow_; }

 private:
  uint8_t *buf_;
  size_t cap_;
  size_t len_ = 0;
  bool overflow_ = false;
};

void addProtocolHeaders() {
  http.addHeader("Tintero-Protocol", "1");
  http.addHeader("Tintero-Firmware", FIRMWARE);
  http.addHeader("Tintero-Power", "usb");
  http.addHeader("Tintero-Formats", "raw1");
  http.addHeader("Tintero-Panel", PANEL);
  http.addHeader("Tintero-RSSI", String(WiFi.RSSI()));
  if (view[0] != '\0') http.addHeader("Tintero-View", view);
}

void printTlsError() {
  char text[120];
  const int code = tls.lastError(text, sizeof text);
  if (code != 0) Serial.printf("  TLS: error %d: %s\n", code, text);
}

}  // namespace

void begin() {
  tls.setCACert(TINTERO_CA_PEM);  // only this CA: not the public ones, not any other
  tls.setCertificate(TINTERO_DEVICE_CERT_PEM);
  tls.setPrivateKey(TINTERO_DEVICE_KEY_PEM);
  tls.setHandshakeTimeout(HANDSHAKE_TIMEOUT_S);

  http.setReuse(true);  // the same connection for several requests in a row
  http.setConnectTimeout(CONNECT_TIMEOUT_MS);
  http.setTimeout(READ_TIMEOUT_MS);
  static const char *wanted[] = {"Retry-After"};
  http.collectHeaders(wanted, 1);
}

const char *deviceId() { return TINTERO_DEVICE_ID; }

// GET (body == nullptr) or POST with a JSON body.
Response request(const char *method, const char *path, const uint8_t *body, size_t bodyLen,
                 uint8_t *buf, size_t cap) {
  Response r;
  const uint32_t t0 = millis();

  // The host name also goes in the TLS handshake (SNI): it must be the same as
  // the one in the server certificate.
  if (!http.begin(tls, TINTERO_HOST, PORT, path, true)) {
    r.status = HTTPC_ERROR_CONNECTION_REFUSED;
    return r;
  }
  addProtocolHeaders();

  if (body == nullptr) {
    r.status = http.GET();
  } else {
    http.addHeader("Content-Type", "application/json");
    r.status = http.POST(const_cast<uint8_t *>(body), bodyLen);
  }
  if (r.status < 0) {
    // There was no HTTP answer: the connection, the TLS or the wait failed.
    Serial.printf("%s %s: %s\n", method, path, HTTPClient::errorToString(r.status).c_str());
    printTlsError();
    http.end();
    tls.stop();
    return r;
  }

  if (http.hasHeader("Retry-After")) r.retryAfterS = http.header("Retry-After").toInt();

  // Limit before reading: if the server announces more than fits, it is not read.
  const int announced = http.getSize();  // Content-Length; -1 if absent
  if (announced > 0 && static_cast<size_t>(announced) > cap) {
    r.tooLarge = true;
  } else if (announced != 0) {
    BoundedSink sink(buf, cap);
    const int got = http.writeToStream(&sink);
    r.tooLarge = sink.overflow();
    if (got >= 0 && !r.tooLarge) r.length = sink.length();
  }

  if (r.tooLarge) {
    // Part of the body is left unread on the connection: it cannot be reused.
    Serial.printf("%s %s: body too large (announced %d, cap %u)\n", method, path, announced,
                  (unsigned)cap);
    http.end();
    tls.stop();
    r.length = 0;
    return r;
  }

  Serial.printf("%s %s → %d, %u bytes, %lu ms\n", method, path, r.status, (unsigned)r.length,
                (unsigned long)(millis() - t0));
  http.end();  // with setReuse(true) the TLS connection stays open for the next one
  return r;
}

Response get(const char *path, uint8_t *buf, size_t cap) {
  return request("GET", path, nullptr, 0, buf, cap);
}

Response post(const char *path, const uint8_t *body, size_t bodyLen, uint8_t *buf, size_t cap) {
  return request("POST", path, body, bodyLen, buf, cap);
}

void setView(const char *viewId) {
  strncpy(view, viewId, sizeof view - 1);
  view[sizeof view - 1] = '\0';
}

void end() {
  http.end();
  tls.stop();
}

}  // namespace tintero
